 s=s.replace('Use the source fields and recorded call count as the evidence boundary; a future integration test should verify the persisted relation.','')
 s=s.replace('The test covers the two early exits only; valid transaction details remain a follow-up.','The original draft covered only early exits; the accepted suite also exercises valid transaction payloads and counters.')
 s=s.replace('The captured `crud-b04-e17-runtime2` run passes two tests.','The original two-case draft is superseded by the five-case root run.')
 s=s.replace('Captured command uses `crud-b04-e17-runtime2` and reports two passing tests.','The initial two-case run is preserved; the accepted expanded run is described below.')
 s='\n\n'.join(x.strip() for x in s.split('\n\n') if x.strip())+'\n\n'+addition+'\n'
 f.write_text(s,encoding='utf-8');print(name,len(s.split()))
